108: /// API tag configuration for flow-based tagging with payment method type support
109: ///
110: /// Environment variable format (case-insensitive):
111: /// - Simple flow: CS__API_TAGS__TAGS__PSYNC=GW_TXN_SYNC
112: /// - With payment method: CS__API_TAGS__TAGS__AUTHORIZE_UPICOLLECT=GW_INIT_COLLECT
113: ///
114: /// TOML format:
115: /// ```toml
116: /// [api_tags.tags]
117: /// psync = "GW_TXN_SYNC"
118: /// authorize_upicollect = "GW_INIT_COLLECT"
119: /// ```
120: ///
121: /// Note: Config crate lowercases env var keys, lookup is case-insensitive
122: #[derive(Clone, Deserialize, Debug, Default, Serialize, PartialEq, config_patch_derive::Patch)]
123: pub struct ApiTagConfig {
124:     #[serde(default)]
125:     pub tags: std::collections::HashMap<String, String>,
126: }
127: 
128: impl ApiTagConfig {
129:     /// Get API tag for a flow, optionally refined by payment method type
130:     ///
131:     /// Lookup order (case-insensitive):
132:     /// 1. If payment_method_type provided: try "flow_paymentmethodtype" (composite key)
133:     /// 2. Fall back to "flow" (simple key)
134:     /// 3. Return None if not found
135:     ///
136:     /// Note: Keys are lowercased for lookup because config crate lowercases env var keys
137:     pub fn get_tag(
138:         &self,
139:         flow: common_utils::events::FlowName,
140:         payment_method_type: Option<common_enums::PaymentMethodType>,
141:     ) -> Option<String> {
142:         let flow_str = flow.as_str();
143: 
144:         payment_method_type.map_or_else(
145:             || {
146:                 let result = self.tags.get(&flow_str.to_lowercase()).cloned();
147:                 if result.is_none() {
148:                     tracing::debug!(
149:                         flow = %flow_str,
150:                         payment_method_type = ?payment_method_type,
151:                         "No API tag configured for flow"
152:                     );
153:                 }
154:                 result
155:             },
156:             |pmt| {
157:                 let composite_key = format!("{flow_str}_{pmt:?}").to_lowercase();
158:                 let result = self.tags.get(&composite_key).cloned();
159:                 if result.is_none() {
160:                     tracing::debug!(
161:                         flow = %flow_str,
162:                         payment_method_type = ?payment_method_type,
163:                         "No API tag configured for flow with payment method type"
164:                     );
165:                 }
166:                 result
167:             },
168:         )
169:     }
170: }
