248: /// Helper function to deserialize a comma-separated string into a HashSet
249: fn deserialize_hashset_inner<T>(value: impl AsRef<str>) -> Result<HashSet<T>, String>
250: where
251:     T: Eq + FromStr + std::hash::Hash,
252:     <T as FromStr>::Err: std::fmt::Display,
253: {
254:     let (values, errors) = value
255:         .as_ref()
256:         .trim()
257:         .split(',')
258:         .map(|s| {
259:             T::from_str(s.trim()).map_err(|error| {
260:                 format!(
261:                     "Unable to deserialize `{}` as `{}`: {error}",
262:                     s.trim(),
263:                     std::any::type_name::<T>()
264:                 )
265:             })
266:         })
267:         .fold(
268:             (HashSet::new(), Vec::new()),
269:             |(mut values, mut errors), result| match result {
270:                 Ok(t) => {
271:                     values.insert(t);
272:                     (values, errors)
273:                 }
274:                 Err(error) => {
275:                     errors.push(error);
276:                     (values, errors)
277:                 }
278:             },
279:         );
280:     if !errors.is_empty() {
281:         Err(format!("Some errors occurred:\n{}", errors.join("\n")))
282:     } else {
283:         Ok(values)
284:     }
285: }
