287: /// Deserializer for Option<HashSet> from comma-separated string
288: /// Handles Option<String> input and returns Option<HashSet> for config_patch_derive::Patch
289: fn deserialize_hashset<'a, D, T>(deserializer: D) -> Result<Option<HashSet<T>>, D::Error>
290: where
291:     D: Deserializer<'a>,
292:     T: Eq + FromStr + std::hash::Hash,
293:     <T as FromStr>::Err: std::fmt::Display,
294: {
295:     match Option::<String>::deserialize(deserializer)? {
296:         Some(s) if !s.trim().is_empty() => deserialize_hashset_inner(s)
297:             .map(Some)
298:             .map_err(D::Error::custom),
299:         _ => Ok(None), // Empty string or None -> None
300:     }
301: }
