416: pub fn workspace_path() -> PathBuf {
417:     if let Ok(manifest_dir) = std::env::var("CARGO_MANIFEST_DIR") {
418:         let mut path = PathBuf::from(manifest_dir.clone());
419: 
420:         // Traverse up until we find the workspace root (a Cargo.toml with [workspace])
421:         while path.parent().is_some() {
422:             let cargo_toml = path.join("Cargo.toml");
423:             if cargo_toml.exists() {
424:                 if let Ok(content) = std::fs::read_to_string(&cargo_toml) {
425:                     if content.contains("[workspace]") {
426:                         return path;
427:                     }
428:                 }
429:             }
430:             path.pop();
431:         }
432: 
433:         // Fallback: return current dir if workspace not found
434:         PathBuf::from(manifest_dir)
435:     } else {
436:         PathBuf::from(".")
437:     }
438: }
